"use strict";
/* =====================================================================
   DATA SCHEMA. COMPANIES is an array; each entry is one account. Ids
   inside an entry only need to be unique within that entry (the renderer
   prefixes them with the entry's `key`). Built to hold ~45 entries.

   entry     : { key, metros: [[branchId|'elsewhere', label], ...],
                 company, branches, people, partners, projects, signals, warmPaths }
   company   : { id, name, aka?, hq, phone, founded, ownership, size, revenue,
                 awards[], trades[], acquisitions[]?, website, apollo,
                 pitchNotes[], competitors[], sources[{label,url}], asOf }
   branches  : [{ id, name, group: 'territory'|'other', address?, phone?,
                 leaderId?  (-> people.id), hiring[]?, note?, link? }]
   people    : [{ id, name, title, branchId ('hq' or branches.id),
                 note?, evidence?, link? }]
   partners  : [{ id, name, kind: 'gc'|'gc-likely'|'owner'|'supplier', note?,
                 metros[]? (text), worksWith[]? (-> branches.id),
                 built[]? (-> projects.id) }]
   projects  : [{ id, name, branchId (a metros key or 'elsewhere'),
                 metro?, gc?, architect?, scope?, value?, size?, note? }]
   signals   : [{ id, name, note?, branchIds[]? (-> branches.id), source?, link? }]
   warmPaths : [{ id, order, name, text, personId? (-> people.id) }]

   Relations shown as "Related" chips on the focused node's card:
     runs        person  -> branch     (people.branchId)
     works with  partner -> branch     (partners.worksWith)
     built       partner -> project    (partners.built)
     hiring      signal  -> branch     (signals.branchIds)
     via         warm path -> person   (warmPaths.personId)
   ===================================================================== */
